import sys
def solve(raw):
 d=list(map(int,raw.split()));n,k=d[:2];a=d[2:];f={0:-1};s=ans=0
 for i,x in enumerate(a):
  s=(s+abs(x))%k
  if s in f:ans=max(ans,i-f[s])
  else:f[s]=i
 return str(ans)
if __name__=='__main__': print(solve(sys.stdin.read()))
